// Generated by tools/backfill-verses.ts — stanzas beyond the seed chordPro,
// taken from the word-timing JSONs in tools/seed-assets/lyrics/. Do not edit by hand.
export const VERSE_EXPANSION: Record<string, string> = {
  "Amazing Grace": "Verse 3\nThrough many\ndangers, toils and snares,\nI have already come;\n'Tis grace\nhath brought me safe\nthus far, And grace\nwill lead me home.\n\nVerse 4\nThe Lord has\npromised good to me,\nHis Word my\nhope secures; He will\nmy Shield and Portion\nbe, As long\nas life endures.\n\nVerse 5\nYea, when this\nflesh and heart\nshall fail, And mortal\nlife shall cease,\nI shall\npossess, within\nthe veil, A life\nof joy and peace.",
  "Be Thou My Vision": "Verse 2\nBe Thou my\nWisdom, and\nThou my true Word;\nI ever with Thee and Thou with me, Lord;\nThou my\ngreat Father, and I Thy true son;\nThou in me dwelling, and\nI with Thee one.\n\nVerse 3\nBe Thou my\nbattle Shield,\nSword for the fight;\nBe Thou my Dignity, Thou my Delight;\nThou my\nsoul's Shelter, Thou my high Tower:\nRaise Thou me heav'nward, O\nPow'r of my pow'r.\n\nVerse 4\nRiches I\nheed not, nor\nman's empty praise,\nThou mine Inheritance, now and always:\nThou and\nThou only, be first in my heart,\nHigh King of Heaven, my\nTreasure Thou art.\n\nVerse 5\nHigh King of\nHeaven, my\nvictory won, May I reach Heav'ns joys, O bright Heaven's Sun!\nHeart of\nmy own heart, whatever befall,\nStill be my Vision, O\nRuler of all.",
  "Holy, Holy, Holy": "Verse 2\nHoly, holy, holy!\nAll saints adore\nThee, Casting down their goldcrowns around the glassy sea;\nCherubim and serphim\nfalling down before\nThee, Who was, and is,\nand evermore shall be.\n\nVerse 3\nHoly, holy, holy!\nthough darkness hide\nThee, Though the eye of sinman Thy glory may not see;\nOnly Thou art holy;\nthere is none beside\nThee, Perfect in pow'r,\nin love, and purity.\n\nVerse 4\nHoly, holy, holy!\nLord God Almighty!\nAll Thy works shall praise\nName, in earth, and sky, and sea;\nHoly, holy, holy;\nmerciful and mighty!\nGod in three Persons,\nblessed Trinity!",
  "Come Thou Fount": "Verse 2\nSorr'wing I shall be in spirit, Till released from flesh and sin,\nYet from what I do inherit, Here Thy praises I'll begin;\nHere I raise my Ebenezer; Here by Thy great help I've come;\nAnd I hope, by Thy good pleasure, Safely to arrive at home.\n\nVerse 3\nJesus sought me when a stranger, Wand'ring from the fold of God;\nHe, to rescue me from danger, Interposed His precious blood;\nHow His kindness yet pursues me Mortal tongue can never tell,\nClothed in flesh, till death shall loose me I cannot proclaim it well.\n\nVerse 4\nO to grace how great a debtor Daily I'm constrained to be!\nLet Thy goodness, like a fetter, Bind my wand'ring heart to Thee.\nProne to wander, Lord, I feel it, Prone to leave the God I love;\nHere's my heart, O take and seal it, Seal it for Thy courts above.\n\nVerse 5\nO that day when freed from sinning, I shall see Thy lovely face;\nClothèd then in blood washed linen How I'll sing Thy sovereign grace;\nCome, my Lord, no longer tarry, Take my ransomed soul away;\nSend thine angels now to carry Me to realms of endless day.",
  "All Creatures of Our God and King": "Verse 2\nThou rushing wind that art so\nYe clouds that sail in Heaven aO\npraise Him! Alleluia!\nThou rising moon, in praise rening, find a voice!\nO praise Him!\nO praise Him!\nAlleluia! Alleluia! Alleluia!\n\nVerse 3\nThou flowing water, pure and\nMake music for thy Lord to\nO praise Him!\nAlleluia! Thou fire so masterful and\nboth warmth and light.\nO praise Him!\nO praise Him!\nAlleluia! Alleluia! Alleluia!\n\nVerse 4\nDear mother earth, who day by\nUnfoldest blessings on our\nO praise Him!\nAlleluia! The flowers and fruits that in thee\nry also show.\nO praise Him!\nO praise Him!\nAlleluia! Alleluia! Alleluia!\n\nVerse 5\nAnd all ye men of tender\nForgiving others, take your\nO sing ye!\nAlleluia! Ye who long pain and sorrow\nHim cast your care!\nO praise Him!\nO praise Him!\nAlleluia! Alleluia! Alleluia!",
  "Silent Night": "Verse 2\nSilent night, holy night, Shepherds quake at the sight; Glories stream\nfrom heaven afar, Heavenly hosts\nsing Alleluia! Christ the Savior is born,\nChrist the Savior is born!\n\nVerse 3\nSilent night, holy night, Son of God, love's pure light; Radiant beams\nfrom Thy holy face\nWith the dawn of redeeming grace, Jesus, Lord, at Thy birth,\nJesus, Lord, at Thy birth.\n\nVerse 4\nSilent night, holy night\nWondrous star, lend thy light; With the angels let\nus sing, Alleluia to\nour King; Christ the Savior is born,\nChrist the Savior is born!",
  "Joy to the World": "Verse 2\nJoy to the earth,\nthe Savior reigns! Let men their songs employ; While fields\nand floods,\nrocks, hills\nand plains\nRepeat the sounding\njoy, Repeat the sounding\njoy, Repeat,\nrepeat, the sounding joy.\n\nVerse 3\nNo more let sins\nand sorrows grow, Nor thorns infest the ground; He comes\nto make\nHis blessings\nflow Far as the curse is\nfound, Far\nas the curse is\nfound, Far\nas, far as,\nthe curse is found.\n\nVerse 4\nHe rules the world\nwith truth and grace, And makes the nations prove The glories\nof His righteousness,\nAnd wonders of His\nlove, And\nwonders of His\nlove, And\nwonders, wonders, of His love.",
  "Hark! The Herald Angels Sing": "Verse 2\nChrist, by highest Heav'n adored;\nChrist the everlasting Lord;\nLate in time, behold Him come,\nOffspring of a virgin's womb.\nVeiled in flesh the Godhead see;\nHail th'incarnate Deity,\nPleased with us in flesh to dwell,\nJesus our Emmanuel.\nHark! the herald angels sing,\n\"Glory to the newborn King!\"\n\nVerse 3\nHail the heav'nly Prince of Peace!\nHail the Sun of Righteousness!\nLight and life to all He brings,\nRis'n with healing in His wings.\nMild He lays His glory by,\nBorn that man no more may die.\nBorn to raise the sons of earth,\nBorn to\ngive them second birth.\nHark! the herald angels sing,\n\"Glory to the newborn King!\"\n\nVerse 4\nCome, Desire of nations, come,\nFix in us Thy humble home;\nRise, the woman's conqu'ring Seed,\nBruise in us the serpent's head.\nNow display Thy saving power, Ruined nature now restore;\nNow in mystic union join\nThine to\nours, and ours to Thine.\nHark! the herald angels sing,\n\"Glory to the newborn King!\"\n\nVerse 5\nAdam's likeness, Lord, efface,\nStamp Thine image in its place:\nSecond Adam from above,\nReinstate us in Thy love.\nLet us Thee, though lost, regain,\nThee, the Life, the inner man:\nO, to all Thyself impart,\nFormed in\neach believing heart.\nHark! the herald angels sing,\n\"Glory to the newborn King!\"",
  "O Little Town of Bethlehem": "Verse 2\nFor Christ is born of Mary, and gathered\nall above, While mortals sleep, the angels keep their watch of\nwond'ring love. O morning stars together, proclaim the holy birth,\nAnd praises sing to God the King, and peace to men\non earth!\n\nVerse 3\nHow silently, how silently, the wondrous\nGift is giv'n;\nSo God imparts to human hearts the blessings\nof His Heav'n.\nNo ear may hear His coming, but in this world of sin,\nWhere meek souls will receive Him still, the dear Christ enters in.\n\nVerse 4\nWhere children pure and happy pray to the\nblessèd Child, Where misery cries out to Thee, Son of the\nmother mild; Where charity stands watching and faith holds wide the door,\nThe dark night wakes, the glory breaks, and Christmas comes once more.\n\nVerse 5\nO holy Child of Bethlehem, descend to\nus, we pray;\nCast out our sin, and enter in, be born in\nus today. We hear the Christmas angels the great glad tidings tell;\nO come to us, abide with us, our Lord Emmanuel!",
  "The First Noel": "Verse 2\nThey lookèd\nup and\nsaw a star\nShining in\nthe east,\nbeyond as them far;\nAnd to\nthe earth it\ngave great light,\nAnd so it continued both day\nand night. Noel,\nNoel, Noel, Noel,\nBorn is the King\nof Israel.\n\nVerse 3\nAnd by\nthe light of\nthat same star\nThree Wise\nMen came\nfrom country as\nfar; To\nseek for a King\nwas their\nintent, And to follow the star\nwherever it went.\nNoel, Noel, Noel,\nNoel, Born is the King\nof Israel.\n\nVerse 4\nThis star\ndrew nigh to\nthe northwest, Over Bethlehem\nit took as its rest;\nAnd there\nit did both\nstop and stay,\nRight over the place\nwhere Jesus lay.\nNoel, Noel, Noel,\nNoel, Born is the King\nof Israel.\n\nVerse 5\nThen did\nthey know assuredly\nWithin that house\nthe King as did lie;\nOne entered\nit them\nfor to see,\nAnd found\nthe Babe\nin poverty. Noel,\nNoel, Noel, Noel,\nBorn is the King\nof Israel.",
  "Angels We Have Heard on High": "Verse 2\nShepherds, why this jubilee?\nWhy your joyous strains prolong?\nWhat the gladsome tidings be\nWhich inspire your heav'nly song?\nGloria, in excelsis Deo!\nGloria, in excelsis Deo!\n\nVerse 3\nCome to Bethlehem and see\nChrist Whose birth the angels sing;\nCome, adore on bended knee,\nChrist the Lord, the newborn King.\nGloria, in excelsis Deo!\nGloria, in excelsis Deo!\n\nVerse 4\nSee Him in a manger laid,\nWhom the choirs of angels praise;\nMary, Joseph, lend your aid,\nWhile our hearts in love we raise.\nGloria, in excelsis Deo!\nGloria, in excelsis Deo!",
  "It Came Upon the Midnight Clear": "Verse 2\nStill through the cloven skies they come With peaceful wings\nunfurled, And still their heavenly music floats O'er all the weary world;\nAbove its sad\nand lowly plains, They bend\non hov'ring wing,\nAnd ever over its Babel sounds The blessèd angels sing.\n\nVerse 3\nYet with the woes\nof sin and strife The world\nhas suffered long;\nBeneath the angel strain have rolled Two thousand years\nof wrong; And man, at war\nwith man, hears not The love-\nsong which\nthey bring; O hush the noise,\nye men of strife And hear the angels sing.\n\nVerse 4\nAnd ye, beneath\nlife's crushing load, Whose forms\nare bending low,\nWho toil along\nthe climbing way With painful steps\nand slow, Look now! for glad\nand golden hours Come swiftly on\nthe wing. O rest beside\nthe weary road, And hear the angels sing!\n\nVerse 5\nFor lo! the days\nare hast'ning on, By prophet- bards\nforetold, When with the ever circling years Comes round the age\nof gold; When peace\nshall over all the earth Its ancient splendors fling,\nAnd the whole world\nsend back the song Which now the angels sing.",
  "O Come, O Come, Emmanuel": "Verse 2\nO come, Thou Wisdom from\non high, Who orderest all things mightily;\nTo us the path of knowledge show,\nAnd teach us in her ways\nto go. Rejoice!\nRejoice! Emmanuel shall come to thee, O Israel.\n\nVerse 3\nO come, Thou Rod of Jesse, free\nThine own from Satan's tyranny;\nFrom depths of hell Thy people save,\nAnd give them vict'ry ov'r\nthe grave. Rejoice!\nRejoice! Emmanuel shall come to thee, O Israel.\n\nVerse 4\nO come, Thou Dayspring, come\nand cheer Our spirits by Thine advent here;\nDisperse the gloomy clouds\nof night, And death's dark shadows put\nto flight. Rejoice!\nRejoice! Emmanuel shall come to thee, O Israel.\n\nVerse 5\nO come, Thou Key of David, come,\nAnd open wide our heav'nly home;\nMake safe the way that leads\non high, And close the path to misery.\nRejoice! Rejoice! Emmanuel\nshall come to thee, O Israel.",
  "Come, Thou Long-Expected Jesus": "Verse 2\nBorn Thy\npeople to de\nliver, Born\na child and\nyet a King,\nBorn to\nreign in\nus forever, Now\nThy gracious\nkingdom bring. By Thine own eternal\nSpirit Rule in all our\nhearts alone; By Thine\nall sufficient\nmerit, Raise\nus to Thy\nglorious throne.",
  "Lo, How a Rose E'er Blooming": "Verse 2\nIsaiah 'twas foretold\nit, the Rose I\nhave in mind;\nWith Mary we behold\nit, the virgin\nmother kind. To show God's love aright,\nshe bore to men a Savior,\nWhen half spent\nwas the night.\n\nVerse 3\nThe shepherds heard the story\nproclaimed by angels bright,\nHow Christ, the Lord of glory\nwas born on\nearth this night.\nTo Bethlehem they sped\nand in the manger found\nHim, As angel\nheralds said.\n\nVerse 4\nThis Flow'r, whose fragrance tender\nwith sweetness fills\nthe air, Dispels with glorious splendor\nthe darkness everywhere;\nTrue Man, yet very God,\nfrom sin and death He saves\nus, And lightens\nev'ry load.\n\nVerse 5\nO Savior, Child of Mary,\nwho felt our\nhuman woe, O\nSavior, King of glory,\nwho dost our\nweakness know; Bring us at length we pray,\nto the bright courts of Heaven,\nAnd to the\nendless day!",
  "Christ the Lord Is Risen Today": "Verse 2\nLove's redeeming work is\ndone, Alleluia! Fought the fight, the battle\nwon, Alleluia! Lo! the Sun's eclipse\nis o'er, Alleluia!\nLo! He sets in blood no\nmore, Alleluia!\n\nVerse 3\nVain the stone, the watch, the\nseal, Alleluia! Christ hath burst the gates of\nhell, Alleluia! Death in vain forbids\nHis rise, Alleluia!\nChrist hath opened paradise,\nAlleluia!\n\nVerse 4\nLives again our glorious\nKing, Alleluia! Where, O death, is now thy\nsting? Alleluia! Once He died our souls\nto save, Alleluia!\nWhere thy victory, O\ngrave? Alleluia!\n\nVerse 5\nSoar we now where Christ hath\nled, Alleluia! Following our exalted\nHead, Alleluia! Made like Him, like Him\nwe rise, Alleluia!\nOurs the cross, the grave, the\nskies, Alleluia!",
  "Crown Him with Many Crowns": "Verse 2\nCrown Him the virgin's Son,\nthe God incarnate born,\nWhose arm those crimson trophies\nwon which now His brow adorn;\nFruit of the mystic rose,\nas of that rose the stem;\nThe root whence mercy ever flows, the Babe of Bethlehem.\n\nVerse 3\nCrown Him the Son of God,\nbefore the worlds began,\nAnd ye who tread where He hath\ntrod, crown Him the Son of Man;\nWho every grief hath known\nthat wrings the human breast,\nAnd takes and bears\nthem for His own, that all in Him may rest.\n\nVerse 4\nCrown Him the Lord of life,\nwho triumphed o'er the grave,\nAnd rose victorious in the\nstrife for those He came to save.\nHis glories now we sing,\nWho died, and rose on high,\nWho died eternal life to bring, and lives that death may die.\n\nVerse 5\nCrown Him the Lord of peace,\nWhose pow'r a scepter sways\nFrom pole to pole, that wars may\ncease, and all be prayer and praise.\nHis reign shall know no end,\nand round His pierced feet\nFair flow'rs of paradise extend their fragrance ever sweet.",
  "All Hail the Power of Jesus' Name": "Verse 2\nLet highborn seraphs tune the lyre, and as they tune it, fall\nBefore His face Who tunes\ntheir choir, and crown\nHim Lord of\nall. Before His face Who tunes\ntheir choir, and crown\nHim Lord\nof all.\n\nVerse 3\nCrown Him, ye morning stars of light, who fixed this floating ball;\nNow hail the strength of Israel's\nmight, and crown\nHim Lord of\nall. Now hail the strength of Israel's\nmight, and crown\nHim Lord\nof all.\n\nVerse 4\nCrown Him, ye martyrs of your God, who from His altar call;\nExtol the Stem of Jesse's\nRod, and crown\nHim Lord of\nall. Extol the Stem of Jesse's\nRod, and crown\nHim Lord\nof all.\n\nVerse 5\nYe seed of Israel's chosen race, ye ransomed from the fall,\nHail Him Who saves you by\nHis grace, and crown\nHim Lord of\nall. Hail Him Who saves you by\nHis grace, and crown\nHim Lord\nof all.",
  "When I Survey the Wondrous Cross": "Verse 2\nForbid it, Lord,\nthat I should\nboast, Save in the death\nof Christ my\nGod! All the vain things\nthat charm\nme most, I\nsacrifice them to\nHis blood.\n\nVerse 3\nSee from His head,\nHis hands, His\nfeet, Sorrow and love\nflow mingled down!\nDid e'er such love\nand sorrow\nmeet, Or thorns compose\nso rich a\ncrown?\n\nVerse 4\nHis dying crimson,\nlike a\nrobe, Spreads o'er His body\non the tree;\nThen I am dead\nto all\nthe globe, And\nall the globe\nis dead to\nme.\n\nVerse 5\nWere the whole realm\nof nature\nmine, That were a present\nfar too small;\nLove so amazing,\nso divine, Demands my soul,\nmy life, my\nall.",
  "O Sacred Head, Now Wounded": "Verse 2\nWhat Thou, my Lord, hast suffered, was all for sinners' gain;\nMine, mine was the transgression, but Thine the deadly pain.\nLo, here\nI fall, my Savior! 'Tis I deserve Thy place;\nLook on\nme with Thy favor, vouchsafe to me Thy grace.\n\nVerse 3\nMen mock and taunt and jeer\nThee, Thou noble countenance,\nThough mighty worlds shall fear\nThee and flee before\nThy glance. How art\nthou pale with anguish, with sore abuse and scorn!\nHow doth\nThy visage languish that once was bright as morn!\n\nVerse 4\nNow from Thy cheeks has vanished their color once\nso fair; From Thy red lips is banished the splendor that\nwas there. Grim death,\nwith cruel rigor, hath robbed Thee of Thy life;\nThus Thou\nhast lost Thy vigor, Thy strength in this sad strife.\n\nVerse 5\nMy burden in Thy Passion, Lord, Thou hast borne\nfor me, For it was my transgression which brought this woe\non Thee. I cast\nme down before\nThee, wrath were my rightful lot;\nHave mercy, I implore\nThee; Redeemer, spurn me not!",
  "The Old Rugged Cross": "Verse 2\nO that old rugged cross,\nso despised by the world,\nHas a wondrous attraction for me;\nFor the dear Lamb of God\nleft His glory above\nTo bear it to dark Calvary.\nSo I'll cherish the old rugged cross,\nTill my trophies at last I lay down;\nI will cling to the old rugged cross,\nAnd exchange it some day for a crown.\n\nVerse 3\nIn that old rugged cross,\nstained with blood so divine,\nA wondrous beauty I see,\nFor 'twas on that old cross\nJesus suffered and died,\nTo pardon and sanctify me.\nSo I'll cherish the old rugged cross,\nTill my trophies at last I lay down;\nI will cling to the old rugged cross,\nAnd exchange it some day for a crown.\n\nVerse 4\nTo the old rugged cross\nI will ever be true;\nIts shame and reproach gladly bear;\nThen He'll call me some day\nto my home far away,\nWhere His glory forever I'll share.\nSo I'll cherish the old rugged cross,\nTill my trophies at last I lay down;\nI will cling to the old rugged cross,\nAnd exchange it some day for a crown.",
  "Praise to the Lord, the Almighty": "Verse 2\nPraise to the Lord, Who o'er all things so wondrously reigneth,\nShelters thee under His wings, yea, so gently sustaineth!\nHast thou not seen\nhow thy desires have been\nGranted in what He ordaineth\n\nVerse 3\nPraise to the Lord, Who hath fearfully, wondrously, made\nthee; Health hath vouchsafed and, when heedlessly falling, hath stayed\nthee. What need or grief\never hath failed of relief?\nWings of His mercy did shade\nthee.\n\nVerse 4\nPraise to the Lord, Who doth prosper thy work and defend\nthee; Surely His goodness and mercy here daily attend\nthee. Ponder anew\nwhat the Almighty can do,\nIf with His love He befriend\nthee.\n\nVerse 5\nPraise to the Lord, Who, when tempests their warfare are waging,\nWho, when the elements madly around thee are raging,\nBiddeth them cease,\nturneth their fury to peace,\nWhirlwinds and waters assuaging.",
  "Immortal, Invisible, God Only Wise": "Verse 2\nUnresting, unhasting, and silent as light,\nNor wanting, nor wasting, Thou rulest in might;\nThy justice, like mountains, high soaring above\nThy clouds, which are fountains of goodness and love.\n\nVerse 3\nTo all, life Thou givest, to both great and small;\nIn all life Thou livest, the true life of all;\nWe blossom and flourish as leaves on the tree,\nAnd wither and perish but naught changeth Thee.\n\nVerse 4\nGreat Father of glory, pure Father of light,\nThine angels adore Thee, all veiling their sight;\nBut of Thy rich graces this grace, Lord, impart\nTake the veil from our face, the vile from our heart.\n\nVerse 5\nAll laud we would render; O help us to see\n'Tis only the splendor of light hideth Thee,\nAnd so let Thy glory, almighty, impart,\nThrough Christ in His story, Thy Christ to the heart.",
  "Praise, My Soul, the King of Heaven": "Verse 2\nPraise Him for His grace and favor\nTo our fathers in distress.\nPraise Him still\nthe same as ever, Slow to chide, and swift to bless.\nAlleluia! Alleluia! Glorious in His faithfulness.\n\nVerse 3\nFather like He tends and spares\nus; Well our feeble frame He knows.\nIn His hands\nHe gently bears us, Rescues us from all our foes.\nAlleluia! Alleluia! Widely yet His mercy flows.\n\nVerse 4\nFrail as summer's flower we flourish,\nBlows the wind and it is gone;\nBut while mortals rise and perish Our God lives unchanging on,\nPraise Him, Praise Him, Hallelujah Praise the High Eternal One!\n\nVerse 5\nAngels, help us to adore\nHim; Ye behold Him face to face;\nSun and moon,\nbow down before Him, Dwellers all in time and space.\nAlleluia! Alleluia! Praise with us the God of grace.",
  "O For a Thousand Tongues to Sing": "Verse 2\nMy gracious Master\nand my God,\nAssist me to\nproclaim, To spread through all\nthe earth abroad\nThe honors of\nThy name.\n\nVerse 3\nJesus! the name\nthat charms our fears,\nThat bids our sorrows\ncease; 'Tis music in\nthe sinner's ears,\n'Tis life, and health,\nand peace.\n\nVerse 4\nHe breaks the pow'r\nof canceled sin,\nHe sets the prisoner\nfree; His blood can make\nthe foulest clean,\nHis blood availed\nfor me.\n\nVerse 5\nHe speaks, and, listening\nto His voice,\nNew life the dead\nreceive, The mournful, broken\nhearts rejoice, The\nhumble poor believe.",
  "And Can It Be": "Verse 2\n'Tis mystery all:\nth'Immortal dies: Who can\nexplore His strange\ndesign? In vain\nthe firstborn seraph tries\nTo sound the depths\nof love divine.\n'Tis mercy all!\nLet earth adore,\nLet angel minds\ninquire no more.\n\nVerse 3\nHe left\nHis Father's throne\nabove So free,\nso infinite His grace?\nEmptied Himself\nof all but love,\nAnd bled for Adam's helpless race:\n'Tis mercy all,\nimmense and free,\nFor O my God,\nit found out me!\n\nVerse 4\nLong my\nimprisoned spirit lay,\nFast bound in sin\nand nature's night;\nThine eye diffused\na quick'ning ray?\nI woke, the dungeon flamed\nwith light;\nMy chains\nfell off, my heart\nwas free, I rose,\nwent forth,\nand followed Thee.\n\nVerse 5\nStill the\nsmall inward voice\nI hear, That whispers all\nmy sins forgiv'n;\nStill the atoning blood\nis near, That quenched\nthe wrath\nof hostile Heav'n.\nI feel\nthe life His wounds\nimpart; I feel\nthe Savior in\nmy heart.",
  "For the Beauty of the Earth": "Verse 2\nFor the\nbeauty of each hour,\nOf the day and of the night,\nHill and\nvale, and tree and flow'r,\nSun and moon, and stars of light.\nLord of all, to Thee we raise,\nThis our hymn of grateful praise.\n\nVerse 3\nFor the\njoy of ear and eye,\nFor the heart and mind's delight,\nFor the\nmystic harmony Linking sense to sound and sight.\nLord of all, to Thee we raise,\nThis our hymn of grateful praise.\n\nVerse 4\nFor the\njoy of human love,\nBrother, sister, parent, child,\nFriends on\nearth and friends above,\nFor all gentle thoughts and mild.\nLord of all, to Thee we raise,\nThis our hymn of grateful praise.\n\nVerse 5\nFor Thy\nChurch, that evermore\nLifteth holy hands above,\nOff'ring up on every shore\nHer pure sacrifice of love.\nLord of all, to Thee we raise,\nThis our hymn of grateful praise.",
  "A Mighty Fortress Is Our God": "Verse 2\nDid we in our\nown strength\nconfide, our striving would be losing; Were not the right\nMan on\nour side, the\nMan of God's\nown choosing: Dost\nask who that\nmay be? Christ\nJesus, it is\nHe; Lord Sabaoth,\nHis name, from\nage to age the same, And He must win the battle.\n\nVerse 3\nAnd though this world,\nwith devils filled, should threaten to undo\nus, We will not fear,\nfor God\nhath willed His truth to triumph through\nus: The Prince\nof Darkness grim,\nwe tremble not\nfor him; His\nrage we can\nendure, for lo, his doom is sure, One little word shall fell\nhim.\n\nVerse 4\nThat word above\nall earthly pow'rs, no thanks to them, abideth; The Spirit and\nthe gifts\nare ours through\nHim who with\nus sideth: Let\ngoods and kindred\ngo, this mortal\nlife also; The\nbody they may\nkill: God's truth abideth still, His kingdom is forever.",
  "To God Be the Glory": "Verse 2\nO perfect redemption, the purchase of blood,\nTo every believer the promise of God;\nThe vilest offender who truly believes,\nThat moment from Jesus a pardon receives.\nPraise the Lord,\npraise the Lord,\nLet the earth hear His voice!\nPraise the Lord,\npraise the Lord,\nLet the people rejoice!\nO come to the Father, through Jesus the Son,\nAnd give Him the glory, great things He has done.\n\nVerse 3\nGreat things He has taught us, great things He has done,\nAnd great our rejoicing through Jesus the Son;\nBut purer, and higher, and greater will be\nOur wonder, our transport, when Jesus we see.\nPraise the Lord,\npraise the Lord,\nLet the earth hear His voice!\nPraise the Lord,\npraise the Lord,\nLet the people rejoice!\nO come to the Father, through Jesus the Son,\nAnd give Him the glory, great things He has done.",
  "Joyful, Joyful, We Adore Thee": "Verse 2\nAll Thy works with joy surround Thee, earth and heaven reflect\nThy rays, Stars and angels sing around Thee, center of unbroken praise.\nField and forest, vale and\nmountain, flowery\nmeadow, flashing sea,\nSinging bird and flowing fountain call us to rejoice in Thee.\n\nVerse 3\nThou art giving and forgiving, ever blessing, ever blessed,\nWellspring of the joy of living, ocean depth of happy rest!\nThou our Father, Christ our\nBrother, all who\nlive in love are Thine;\nTeach us how\nto love each other, lift us to the joy divine.\n\nVerse 4\nMortals, join the happy chorus, which the morning stars began;\nFather love is reigning o'er us, brother love binds man to man.\nEver singing, march we\nonward, victors\nin the midst of strife,\nJoyful music leads us Sunward in the triumph song of life.",
  "Holy God, We Praise Thy Name": "Verse 2\nHark! the loud\ncelestial hymn Angel choirs above\nare raising, Cherubim\nand seraphim, In\nunceasing chorus praising;\nFill the\nheavens with sweet\naccord: Holy, holy, holy, Lord.\n\nVerse 3\nLo! the apostolic train\nJoin the sacred Name\nto hallow; Prophets swell\nthe loud\nrefrain, And the white\nrobed martyrs follow;\nAnd from\nmorn to set\nof sun, Through\nthe Church\nthe song\ngoes on.\n\nVerse 4\nHoly Father, Holy Son,\nHoly Spirit, Three\nwe name Thee;\nWhile in essence only One,\nUndivided God\nwe claim Thee;\nAnd adoring bend\nthe knee, While\nwe own\nthe mystery.",
  "My Faith Looks Up to Thee": "Verse 2\nMay Thy rich grace impart\nStrength to my fainting heart,\nmy zeal inspire!\nAs Thou hast died for me,\nO may my love to Thee,\nPure warm, and changeless be, a living\nfire!\n\nVerse 3\nWhile life's dark maze I tread,\nAnd griefs around me spread,\nbe Thou my Guide;\nBid darkness turn to day,\nwipe sorrow's tears away,\nNor let me ever stray from Thee\naside.\n\nVerse 4\nWhen ends life's transient dream,\nWhen death's cold sullen stream\nover me roll;\nBlest Savior, then in love,\nfear and distrust remove;\nO bear me safe above, a ransomed\nsoul!",
  "Abide with Me": "Verse 2\nSwift to its close\nebbs out life's little day;\nEarth's joys grow dim;\nits glories pass away;\nChange and decay\nin all around I see;\nO Thou who changest not, abide\nwith me.\n\nVerse 3\nNot a brief glance\nI beg, a passing word;\nBut as Thou dwell'st\nwith Thy disciples, Lord,\nFamiliar, condescending, patient, free.\nCome not to sojourn, but abide\nwith me.\n\nVerse 4\nCome not in terrors,\nas the King of kings,\nBut kind and good,\nwith healing in Thy wings,\nTears for all woes,\na heart for every plea?\nCome, Friend of sinners, and thus bide\nwith me.\n\nVerse 5\nThou on my head\nin early youth didst smile;\nAnd, though rebellious\nand perverse meanwhile,\nThou hast not left\nme, oft as I left Thee,\nOn to the close, O Lord, abide\nwith me.",
  "Be Still, My Soul": "Verse 2\nBe still, my soul:\nthy God doth undertake\nTo guide the future, as He has the past.\nThy hope, thy confidence let nothing shake;\nAll now mysterious shall be bright at last.\nBe still, my soul:\nthe waves and winds still know\nHis voice Who ruled\nthem while He dwelt below.\n\nVerse 3\nBe still, my soul:\nwhen dearest friends depart,\nAnd all is darkened in the vale of tears,\nThen shalt thou better know His love, His heart,\nWho comes to soothe\nthy sorrow and thy fears.\nBe still, my soul:\nthy Jesus can repay\nFrom His own fullness all He takes away.\n\nVerse 4\nBe still, my soul:\nthe hour is hast'ning on\nWhen we shall be\nforever with the Lord.\nWhen disappointment, grief and fear are gone,\nSorrow forgot, love's purest joys restored.\nBe still, my soul:\nwhen change and tears are past\nAll safe and blessèd we shall meet at last.\n\nVerse 5\nBe still, my soul:\nbegin the song of praise\nOn earth, believing, to Thy Lord on high;\nAcknowledge Him in all thy words and ways,\nSo shall He view\nthee with a well pleased eye.\nBe still, my soul:\nthe Sun of life divine\nThrough passing clouds\nshall but more brightly shine.",
  "What a Friend We Have in Jesus": "Verse 2\nHave we trials and temptations?\nIs there trouble anywhere?\nWe should never be discouraged;\ntake it to the Lord in prayer.\nCan we find a friend so faithful\nwho will all our sorrows share?\nJesus knows our every weakness;\ntake it to the Lord in prayer.\n\nVerse 3\nAre we weak and heavy laden,\ncumbered with a load of care?\nPrecious Savior, still our refuge,\ntake it to the Lord in prayer.\nDo your friends despise, forsake\nyou? Take it to the Lord in prayer!\nIn His arms He'll take and shield\nyou; you will find a solace there.\n\nVerse 4\nBlessed Savior, Thou hast promised\nThou wilt all our burdens bear\nMay we ever, Lord, be bringing\nall to Thee in earnest prayer.\nSoon in glory bright unclouded\nthere will be no need for prayer\nRapture, praise and endless worship\nwill be our sweet portion there.",
  "Rock of Ages": "Verse 2\nNot the labor\nof my hands\nCan fulfill Thy law's demands;\nCould my zeal\nno respite know,\nCould my tears\nforever flow, All for sin\ncould not atone;\nThou must save,\nand Thou alone.\n\nVerse 3\nNothing in my\nhand I bring,\nSimply to the cross I cling;\nNaked, come to Thee for dress;\nHelpless look to Thee for grace;\nFoul, I to\nthe fountain fly;\nWash me, Savior, or I die.\n\nVerse 4\nWhile I draw\nthis fleeting breath,\nWhen mine eyes\nshall close in death,\nWhen I soar\nto worlds unknown,\nSee Thee on\nThy judgment throne,\nRock of Ages,\ncleft for me,\nLet me hide\nmyself in Thee.",
  "Nearer, My God, to Thee": "Verse 2\nThough like the wanderer,\nthe sun gone down,\nDarkness be over me,\nmy rest a stone.\nYet in my dreams\nI'd be nearer,\nmy God to Thee.\nThen evermore to be\nNearer to Thee!\n\nVerse 3\nNearer, my Lord,\nto thee, Nearer\nto thee! Who\nto the cross\ndidst come, Dying\nfor me! Strengthen\nmy willing feet,\nHold me in service sweet\n\nVerse 4\nNearer, O Comforter,\nNearer to thee!\nWho with my loving Lord\nDwellest with me!\nGrant me thy fellowship!\nHelp me each day\nto keep\n\nVerse 5\nBut to be nearer still,\nBring me, O God,\nNot by the visioned steeps\nAngels have trod.\nHere where thy cross\nI see, Jesus,\nI wait for thee,",
  "I Need Thee Every Hour": "Verse 2\nI need Thee ev'ry hour,\nStay Thou\nnear by; Temptations lose their pow'r\nWhen Thou\nart nigh. I need Thee, O I need Thee;\nEv'ry hour I need Thee; O bless\nme now, my Savior, I come\nto Thee!\n\nVerse 3\nI need Thee ev'ry hour,\nIn joy\nor pain; Come quickly and abide,\nOr life\nis vain. I need Thee, O I need Thee;\nEv'ry hour I need Thee; O bless\nme now, my Savior, I come\nto Thee!\n\nVerse 4\nI need Thee ev'ry hour,\nTeach me\nThy will; And Thy rich promises\nIn me\nfulfill. I need Thee, O I need Thee;\nEv'ry hour I need Thee; O bless\nme now, my Savior, I come\nto Thee!\n\nVerse 5\nI need Thee ev'ry hour,\nMost Holy\nOne; O make me Thine indeed,\nThou blessed\nSon! I need Thee, O I need Thee;\nEv'ry hour I need Thee; O bless\nme now, my Savior, I come\nto Thee!",
  "He Leadeth Me": "Verse 2\nSometimes mid scenes of deepest gloom, Sometimes where Eden's\nbowers bloom, By waters still, ov'r troubled sea, Still\n'tis His hand\nthat leadeth me. He leadeth me, He leadeth\nme, By His own hand\nHe leadeth me; His faithful follow'r I would\nbe, For by His hand\nHe leadeth me.\n\nVerse 3\nLord, I would place my hand in Thine, Nor ever murmur\nnor repine; Content, whatever lot I see, Since\n'tis my God\nthat leadeth me. He leadeth me, He leadeth\nme, By His own hand\nHe leadeth me; His faithful follow'r I would\nbe, For by His hand\nHe leadeth me.\n\nVerse 4\nAnd when my task on earth is done, When by\nThy grace the\nvict'ry's won, E'en death's cold wave I will not flee, Since\nGod through Jordan\nleadeth me. He leadeth me, He leadeth\nme, By His own hand\nHe leadeth me; His faithful follow'r I would\nbe, For by His hand\nHe leadeth me.",
  "Blessed Assurance": "Verse 2\nPerfect submission, perfect delight,\nVisions of rapture now burst on my sight;\nAngels descending bring from above\nEchoes of mercy, whispers of love.\nThis is my story, this is my song,\nPraising my Savior, all the day long;\nThis is my story, this is my song,\nPraising my Savior, all the day long.\n\nVerse 3\nPerfect submission, all is at rest\nI in my Savior am happy and blest,\nWatching and waiting, looking above,\nFilled with His goodness, lost in His love.\nThis is my story, this is my song,\nPraising my Savior, all the day long;\nThis is my story, this is my song,\nPraising my Savior, all the day long.",
  "Guide Me, O Thou Great Jehovah": "Verse 2\nOpen now the crystal\nfountain, Whence the healing stream doth flow;\nLet the fire and cloudy\npillar Lead me all my\njourney through. Strong\nDeliv'rer, strong Deliv'rer, Be Thou still my Strength and Shield;\nBe Thou still\nmy Strength and Shield.\n\nVerse 3\nLord, I trust Thy mighty\npower, Wondrous are Thy works of old;\nThou deliver'st Thine\nfrom thralldom, Who for naught themselves had sold:\nThou didst conquer, Thou didst conquer, Sin, and Satan and the grave,\nSin, and Satan\nand the grave.\n\nVerse 4\nWhen I tread the verge\nof Jordan, Bid my anxious fears subside;\nDeath of deaths, and hell's\ndestruction, Land me safe on\nCanaan's side. Songs\nof praises, songs of praises, I will ever give to Thee;\nI will ever\ngive to Thee.\n\nVerse 5\nMusing on my habitation, Musing on my heav'nly home,\nFills my soul with holy\nlongings: Come, my Jesus,\nquickly come; Vanity is all I see;\nLord, I long to be with Thee!\nLord, I long\nto be with Thee!",
  "Take My Life and Let It Be": "Verse 2\nTake my hands,\nand let them move\nat the impulse of\nThy love. Take\nmy feet,\nand let them be\nswift and beautiful\nfor Thee.\n\nVerse 3\nTake my voice,\nand let me sing\nalways, only, for\nmy King. Take\nmy lips,\nand let them be\nfilled with messages\nfrom Thee.\n\nVerse 4\nTake my silver and\nmy gold; not\na mite\nwould I withhold.\nTake my intellect,\nand use every pow'r\nas Thou shalt choose.\n\nVerse 5\nTake my will,\nand make it Thine;\nit shall be\nno longer\nmine. Take my heart,\nit is Thine own;\nit shall be\nThy royal throne.",
  "Pass Me Not, O Gentle Savior": "Verse 2\nLet me at Thy throne of mercy\nFind a sweet relief,\nKneeling there in deep contrition;\nHelp my unbelief.\nSavior, Savior, Hear my humble cry;\nWhile on others Thou art calling,\nDo not pass me by.\n\nVerse 3\n3, Trusting only in Thy merit,\nWould I seek Thy face;\nHeal my wounded, broken spirit,\nSave me by Thy grace.\nSavior, Savior, Hear my humble cry;\nWhile on others Thou art calling,\nDo not pass me by.\n\nVerse 4\nThou the Spring of all my comfort,\nMore than life to me,\nWhom have I on earth beside\nThee? Whom in Heav'n but Thee?\nSavior, Savior, Hear my humble cry;\nWhile on others Thou art calling,\nDo not pass me by.",
  "Jesus Shall Reign": "Verse 2\nFor Him shall endless\nprayer be\nmade, And praises throng\nto crown His\nhead; His Name, like sweet\nperfume shall\nrise With every morning sacrifice.\n\nVerse 3\nPeople and realms\nof every\ntongue Dwell on His love\nwith sweetest song;\nAnd infant voices\nshall proclaim Their\nearly blessings on\nHis Name.\n\nVerse 4\nBlessings abound where'er\nHe reigns; The\nprisoner leaps to\nlose his chains,\nThe weary find\neternal rest, And\nall the sons\nof want are\nblest.\n\nVerse 5\nWhere He displays\nHis healing\npower Death and the curse\nare known no\nmore; In Him the tribes\nof Adam\nboast More blessings than\ntheir father lost.",
  "Rescue the Perishing": "Verse 2\nThough they are slighting Him,\nstill He is waiting, Waiting the penitent child to receive;\nPlead with them earnestly,\nplead with them gently; He will forgive they should only believe.\nRescue the perishing,\ncare for the dying, Jesus is merciful, Jesus will save.\n\nVerse 3\nDown in the human heart,\ncrushed by the tempter, Feelings lie buried that grace can restore;\nTouched by a loving heart,\nwakened by kindness, Chords that were broken will vibrate once more.\nRescue the perishing,\ncare for the dying, Jesus is merciful, Jesus will save.\n\nVerse 4\nRescue the perishing,\nduty demands it; Strength for thy labor the Lord will provide;\nBack to the narrow way\npatiently win them; Tell the poor wand'rer a Savior has died.\nRescue the perishing,\ncare for the dying, Jesus is merciful, Jesus will save.",
  "The Church's One Foundation": "Verse 2\nShe is from every nation, Yet one o'er all the earth;\nHer charter of salvation, One Lord, one faith, one birth;\nOne holy Name she blesses, Partakes one holy food,\nAnd to one hope she presses, With every grace endued.\n\nVerse 3\nThe Church shall never perish! Her dear Lord to defend,\nTo guide, sustain, and cherish, Is with her to the end:\nThough there be those who hate\nher, And false sons in her pale,\nAgainst or foe or traitor She ever shall prevail.\n\nVerse 4\nThough with a scornful wonder Men see her sore oppressed,\nBy schisms rent asunder, By heresies distressed:\nYet saints their watch are keeping, Their cry goes up, 'How long?'\nAnd soon the night of weeping Shall be the morn of song!\n\nVerse 5\n'Mid toil and tribulation, And tumult of her war,\nShe waits the consummation Of peace forevermore;\nTill, with the vision glorious, Her longing eyes are blest,\nAnd the great Church victorious Shall be the Church at rest.",
  "Blest Be the Tie That Binds": "Verse 2\nBefore our Father's throne\nWe pour our ardent prayers;\nOur fears, our hopes,\nour aims are one Our comforts and our cares.\n\nVerse 3\nWe share each other's woes,\nOur mutual burdens bear;\nAnd often for each other flows The sympathizing tear.\n\nVerse 4\nWhen we asunder part,\nIt gives us inward pain;\nBut we shall still\nbe joined in heart, And hope to meet again.\n\nVerse 5\nThis glorious hope revives\nOur courage by the way;\nWhile each in expectation lives, And longs to see the day.",
  "We Gather Together": "Verse 2\nBeside us to guide us, our God\nwith us joining, Ordaining, maintaining His kingdom divine;\nSo from the beginning the fight\nwe were winning; Thou, Lord, were at our side,\nall forgets glory be Thine!\n\nVerse 3\nWe all do extol Thee, Thou Leader triumphant, And pray\nthat Thou still our Defender will be.\nLet Thy congregation escape\ntribulation; Thy Name be ever praised!\nO forgets Lord, make us free!",
  "How Firm a Foundation": "Verse 2\nIn every condition, in sickness, in health;\nIn poverty's vale,\nor abounding in wealth;\nAt home and abroad,\non the land,\non the sea,\nAs thy days demand,\nshall thy strength\never be.\n\nVerse 3\nFear not, I am with\nthee, O be\nnot dismayed, For\nI am thy God\nand will still\ngive thee aid;\nI'll strengthen and help\nthee, and cause\nthee to stand\nUpheld by My righteous, omnipotent hand.\n\nVerse 4\nWhen through the deep waters I call\nthee to go,\nThe rivers of woe\nshall not thee\noverflow; For I\nwill be with\nthee, thy troubles to bless,\nAnd sanctify to\nthee thy deepest distress.\n\nVerse 5\nWhen through fiery trials thy pathways shall lie,\nMy grace, all sufficient, shall be\nthy supply; The\nflame shall not hurt\nthee; I only design\nThy dross to consume,\nand thy gold\nto refine.",
  "When the Roll Is Called Up Yonder": "Verse 2\nOn that bright\nand cloudless morning when the dead in Christ shall rise,\nAnd the glory of His resurrection share;\nWhen His chosen ones\nshall gather to their home beyond the skies,\nAnd the roll is called up yonder, I'll be there.\nWhen the roll\nis called up yonder, When the roll\nis called up yonder, When the roll\nis called up yonder,\nWhen the roll is called up yonder, I'll be there.\n\nVerse 3\nLet us labor for\nthe Master from the dawn till setting sun,\nLet us talk of all His wondrous love and care;\nThen when all\nof life is over, and our work on earth is done,\nAnd the roll is called up yonder, I'll be there.\nWhen the roll\nis called up yonder, When the roll\nis called up yonder, When the roll\nis called up yonder,\nWhen the roll is called up yonder, I'll be there.",
  "As with Gladness Men of Old": "Verse 2\nAs with\njoyful steps they sped\nTo that lowly manger bed\nThere to\nbend the knee before\nHim whom Heav'n and earth adore;\nSo may we with willing feet\nEver seek Thy mercy seat.\n\nVerse 3\nAs they\noffered gifts most rare\nAt that manger rude and bare;\nSo may\nwe with holy joy,\nPure and free from sin's alloy,\nAll our costliest treasures bring,\nChrist, to Thee, our heav'nly King.\n\nVerse 4\nHoly Jesus, ev'ry day\nKeep us in the narrow way;\nAnd, when\nearthly things are past,\nBring our ransomed souls at last\nWhere they need no star to guide,\nWhere no clouds Thy glory hide.\n\nVerse 5\nIn the\nheav'nly country bright,\nNeed they no created light;\nThou its\nLight, its Joy, its Crown,\nThou its Sun which goes not down;\nThere forever may we sing\nAlleluias to our King!",
  "Angels from the Realms of Glory": "Verse 2\nShepherds, in the field abiding, Watching o'er your flocks by night,\nGod with us is now residing; Yonder shines the\ninfant light: Come\nand worship, come and worship, Worship Christ, the newborn King.\n\nVerse 3\nSages, leave your contemplations, Brighter visions beam afar;\nSeek the great Desire of nations; Ye have seen His\nnatal star. Come\nand worship, come and worship, Worship Christ, the newborn King.\n\nVerse 4\nSaints, before the altar bending, Watching long in hope and fear;\nSuddenly the Lord, descending, In His temple\nshall appear. Come\nand worship, come and worship, Worship Christ, the newborn King.\n\nVerse 5\nSinners, wrung with true repentance, Doomed for guilt to endless pains,\nJustice now revokes the sentence, Mercy calls you;\nbreak your chains.\nCome and worship, come and worship, Worship Christ, the newborn King.",
  "I Heard the Bells on Christmas Day": "Verse 2\nAnd thought how, as the day\nhad come, The belfries of all Christendom Had rolled\nalong th'unbroken song Of peace on earth, good will to men.\n\nVerse 3\nTill ringing, singing on\nits way The world revolved from night\nto day, A voice,\na chime, a chant\nsublime Of peace on earth, good will to men.\n\nVerse 4\nAnd in despair I bowed\nmy head \"There is no peace on earth,\"\nI said, \"For hate\nis strong and mocks\nthe song Of peace on earth, good will to men.\"\n\nVerse 5\nThen pealed the bells more loud\nand deep: \"God is not dead, nor doth\nHe sleep; The wrong\nshall fail, the right\nprevail With peace on earth, good will to men.\"",
  "Of the Father's Love Begotten": "Verse 2\nAt His Word they were created;\nHe commanded; it\nwas done: Heav'n and earth and depths of ocean\nIn their threefold order one;\nAll that grows beneath the shining\nOf the moon\nand burning sun,\nEvermore and evermore!\n\nVerse 3\nHe is found in human fashion,\nDeath and sorrow here\nto know, That the race of Adam's children,\nDoomed by law to endless woe,\nMay not henceforth die and perish\nIn the dreadful gulf below,\nEvermore and evermore!\n\nVerse 4\nOh that birth forever blessèd!\nWhen the virgin, full\nof grace, By the Holy Ghost conceiving,\nBare the Savior of\nour race; And the Babe, the world's Redeemer,\nFirst revealed\nHis sacred face,\nEvermore and evermore!\n\nVerse 5\nO ye heights of heav'n adore\nHim; Angel hosts, His praises sing;\nPow'rs, dominions, bow before\nHim, and extol our God\nand King: Let no tongue on earth be silent,\nEvery voice\nin concert ring,\nEvermore and evermore!",
  "Lo! He Comes with Clouds Descending": "Verse 2\nEv'ry eye\nshall now\nbehold Him Robed\nin dreadful majesty;\nThose who\nset at\nnaught and\nsold Him, Pierced\nand nailed Him\nto the\ntree, Deeply wailing,\ndeeply wailing, deeply wailing,\nShall the\ntrue Messiah see.\n\nVerse 3\nEv'ry island,\nsea, and\nmountain, Heav'n and earth,\nshall flee\naway; All who\nhate Him\nmust, confounded, Hear\nthe trump proclaim\nthe day:\nCome to judgment!\nCome to judgment!\nCome to judgment!\nCome to\njudgment! Come away!\n\nVerse 4\nNow redemption,\nlong expected, See\nin solemn pomp\nappear; All His\nsaints, by\nman rejected, Now\nshall meet Him\nin the\nair: Hallelujah! Hallelujah!\nHallelujah! See the\nday of God\nappear!\n\nVerse 5\nAnswer Thine\nown bride\nand Spirit, Hasten, Lord,\nthe gen'ral\ndoom! The new\nHeav'n and\nearth inherit, Take\nThy pining exiles\nhome: All\ncreation, all\ncreation, all\ncreation, Travails!\ngroans! and bids\nThee come!",
  "All Glory, Laud, and Honor": "Verse 2\nAll glory, laud and honor, To Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThe company of angels Are praising Thee on High,\nAnd mortal men and all\nthings Created make reply.\n\nVerse 3\nAll glory, laud and honor, To Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThe people of the Hebrews With palms before Thee went;\nOur prayer and praise and anthems Before Thee we present.\n\nVerse 4\nAll glory, laud and honor, To Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nTo Thee, before Thy passion, They sang their hymns of praise;\nTo Thee, now high exalted, Our melody we raise.\n\nVerse 5\nAll glory, laud and honor, To Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThou didst accept their praises; Accept the prayers we bring,\nWho in all good delightest, Thou good and gracious King.",
  "Hosanna, Loud Hosanna": "Verse 2\nFrom Olivet they followed mid an\nexultant crowd, The victor\npalm branch waving, and chanting clear and loud.\nThe Lord of men and angels rode\non in lowly state,\nNor scorned that\nlittle children should on\nHis bidding wait.\n\nVerse 3\n\"Hosanna in the highest!\" that ancient song we sing,\nFor Christ is\nour Redeemer, the Lord\nof heav'n our King.\nO may we ever praise\nHim with\nheart and life and voice,\nAnd in His\nblissful presence eternally rejoice!",
  "I Know That My Redeemer Lives": "Verse 2\nHe lives to bless\nme with His\nlove, He lives to plead\nfor me above.\nHe lives my hungry\nsoul to\nfeed, He lives to help\nin time of\nneed.\n\nVerse 3\nHe lives triumphant\nfrom the\ngrave, He lives eternally\nto save, He\nlives all glorious\nin the\nsky, He lives exalted there\non high.\n\nVerse 4\nHe lives to grant\nme rich supply,\nHe lives to guide\nme with His\neye, He lives to comfort\nme when\nfaint, He lives to hear\nmy soul's complaint.\n\nVerse 5\nHe lives to silence\nall my\nfears, He lives to wipe\naway my tears\nHe lives to calm\nmy troubled\nheart, He lives all blessings to\nimpart.",
  "Go to Dark Gethsemane": "Verse 2\nFollow to the judgment hall,\nview the Lord of Life arraigned;\nO the wormwood and the gall!\nO the pangs His soul sustained!\nShun not suff'ring, shame, or loss;\nlearn from Christ to bear the cross.\n\nVerse 3\nCalv'ry's mournful mountain climb;\nthere, adoring at His feet,\nMark that miracle of time,\nGod's own sacrifice complete.\n\"It is finished!\" hear Him cry;\nlearn from Jesus Christ to die.\n\nVerse 4\nEarly hasten to the tomb\nwhere they laid His breathless clay;\nAll is solitude and gloom.\nWho has taken Him away?\nChrist is ris'n! He meets our eyes;\nSavior, teach us so to rise.",
  "Beneath the Cross of Jesus": "Verse 2\nO safe and happy shelter, O refuge tried and sweet,\nO trysting place where Heaven's love and Heaven's justice meet!\nAs to the holy patriarch that wondrous dream was giv'n,\nSo seems my Savior's cross to me, a ladder up to heav'n.\n\nVerse 3\nThere lies beneath its shadow but on the further side\nThe darkness of an awful grave that gapes both deep and wide\nAnd there between us stands the cross two arms outstretched to save\nA watchman set to guard the way from that eternal grave.\n\nVerse 4\nUpon that cross of Jesus mine eye at times can see\nThe very dying form of One Who suffered there for me;\nAnd from my stricken heart with tears two wonders I confess;\nThe wonders of redeeming love and my unworthiness.\n\nVerse 5\nI take, O cross, thy shadow for my abiding place;\nI ask no other sunshine than the sunshine of His face;\nContent to let the world go by to know\nno gain or loss,\nMy sinful self my only shame, my glory all the cross.",
  "Hallelujah! What a Savior": "Verse 2\nBearing shame and scoffing rude,\nIn my place condemned He stood;\nSealed my pardon with His blood. Hallelujah! What a Savior!\n\nVerse 3\nGuilty, vile, and helpless we;\nSpotless Lamb of God was He;\n\"Full atonement!\" can it be? Hallelujah! What a Savior!\n\nVerse 4\nLifted up was He to die;\n\"It is finished!\" was His cry;\nNow in Heav'n exalted high. Hallelujah! What a Savior!\n\nVerse 5\nWhen He comes, our glorious King,\nAll His ransomed home to bring,\nThen anew His song we'll sing: Hallelujah! What a Savior!",
  "Whiter than Snow": "Verse 2\nLord Jesus, look down from Thy throne in the skies,\nAnd help me to make a complete sacrifice;\nI give up myself,\nand whatever I know,\nNow wash me and I shall be whiter than snow.\nWhiter than snow,\nyes, whiter than snow;\nNow wash me, and I shall be whiter than snow.\n\nVerse 3\nLord Jesus, for this I most humbly entreat,\nI wait, blessed Lord, at Thy crucified feet,\nBy faith, for my cleansing, I see Thy blood flow,\nNow wash me and I shall be whiter than snow.\nWhiter than snow,\nyes, whiter than snow;\nNow wash me, and I shall be whiter than snow.\n\nVerse 4\nLord Jesus, Thou seest I patiently wait,\nCome now, and within me a new heart create;\nTo those who have sought\nThee, Thou never said'st ``No,''\nNow wash me and I shall be whiter than snow.\nWhiter than snow,\nyes, whiter than snow;\nNow wash me, and I shall be whiter than snow.",
  "O the Deep, Deep Love of Jesus": "Verse 2\nO the\ndeep, deep love\nof Jesus, spread\nHis praise\nfrom shore\nto shore! How\nHe loveth, ever\nloveth, changeth\nnever, nevermore! How\nHe watches o'er\nHis loved ones,\ndied to\ncall them all\nHis own; How\nfor them He\nintercedeth, watcheth\no'er them from\nthe throne!\n\nVerse 3\nO the\ndeep, deep love\nof Jesus, love\nof every love\nthe best! 'Tis\nan ocean full\nof blessing, 'tis\na haven giving\nrest! O the\ndeep, deep love\nof Jesus, 'tis\na heav'n of\nheav'ns to\nme; And it\nlifts me up\nto glory, for\nit lifts\nme up\nto Thee!",
  "The God of Abraham Praise": "Verse 2\nThe God of Abr'ham praise,\nat Whose supreme command\nFrom earth I rise and seek the joys at His\nright hand; I all on earth forsake,\nits wisdom,\nfame, and pow'r;\nAnd Him my only Portion\nmake, my\nShield and Tow'r.\n\nVerse 3\nThe God of Abr'ham praise,\nWhose all sufficient grace\nShall guide me all my happy days, in all\nmy ways. He calls a worm His friend,\nHe calls\nHimself my God!\nAnd He shall save me to the\nend, thro'\nJesus' blood.\n\nVerse 4\nHe by Himself has sworn;\nI on His oath depend,\nI shall, on eagle wings upborne, to Heav'n\nascend. I shall behold His face;\nI shall\nHis pow'r adore,\nAnd sing the wonders of His\ngrace forevermore.\n\nVerse 5\nTho' nature's strength decay,\nand earth and hell withstand,\nTo Canaan's bounds I urge my way, at His\ncommand. The wat'ry deep I pass,\nwith Jesus\nin my view;\nAnd thro' the howling wilderness my\nway pursue.",
  "Praise the Lord! Ye Heavens, Adore Him": "Verse 2\nPraise the Lord, for He is glorious; Never shall His promise\nfail. God hath made\nHis saints victorious; Sin and death shall not prevail.\nPraise the God\nof our salvation; Hosts on high, His pow'r proclaim.\nHeav'n and earth and all creation, Laud and\nmagnify His\nname.\n\nVerse 3\nWorship, honor, glory, blessing, Lord, we offer unto\nThee. Young and old, Thy praise expressing, In glad homage bend the\nknee. All the saints\nin Heav'n adore\nThee; We would bow before Thy\nthrone. As Thine angels serve before\nThee, So on\nearth Thy\nwill be\ndone.",
  "I Sing the Mighty Power of God": "Verse 2\nI sing the\ngoodness of the Lord, That filled\nthe earth with food:\nHe formed the\ncreatures with His word, And then\npronounced them good.\nLord, how Thy wonders are displayed, Where'er I turn my eye;\nIf I survey the ground I tread, Or gaze\nupon the sky.\n\nVerse 3\nThere's not a\nplant or flow'r below, But makes\nThy glories known;\nAnd clouds arise and tempests blow, By order from Thy throne.\nCreatures that borrow life from\nThee Are\nsubject to Thy care:\nThere's not a\nplace where we can flee, But God\nis present there.",
  "Come, Ye Disconsolate": "Verse 2\nJoy of the desolate,\nlight of the straying,\nHope of the penitent,\nfadeless and pure,\nHere speaks the Comforter,\ntenderly saying,\n\"Earth has no sorrow\nthat Heav'n cannot cure.\"\n\nVerse 3\nHere see the Bread of Life;\nsee waters flowing\nForth from the throne of God,\npure from above;\nCome to the feast of love;\ncome, ever\nknowing Earth\nhas no sorrow\nbut Heav'n can remove.",
  "Breathe on Me, Breath of God": "Verse 2\nBreathe on me, breath of God,\nUntil my heart is pure,\nUntil with Thee I will one will, To do and to\nendure.\n\nVerse 3\nBreathe on me, breath of God,\nSo shall I never die,\nBut live with Thee the perfect life Of Thine eternity.",
  "Faith of Our Fathers": "Verse 2\nFaith of our fathers, we\nwill strive To win all nations unto Thee;\nAnd through the truth\nthat comes\nfrom God, We all shall then\nbe truly free.\nFaith of our fathers, holy faith!\nWe will be true\nto thee till death.\n\nVerse 3\nFaith of our fathers, we\nwill love Both friend and foe\nin all\nour strife; And preach Thee, too,\nas love\nknows how By kindly words\nand virtuous life.\nFaith of our fathers, holy faith!\nWe will be true\nto thee till death.",
  "Jesus Loves Me": "Verse 2\ntle in.\nsus ble\nso.\n\nVerse 3\nforth Thee.\nsus ble\nso.",
  "I Stand Amazed in the Presence": "Verse 2\nFor me it was in the garden He pray'd \"Not my will, but Thine;\"\nHe had no tears for His own griefs, But sweat drops of blood for mine.\n\nVerse 3\nIn pity angels beheld Him, And came from the world of light\nTo comfort Him in the sorrows, He bore for my soul that night.\n\nVerse 4\nWhen with the ransomed in glory His face I at last shall see,\n'Twill be my joy thro' the ages, To sing of His love for me.",
  "More Love to Thee": "Verse 2\nOnce earthly joy I craved,\nSought peace and rest;\nNow thee alone I seek,\nGive what is best;\nThis all my pray'r shall be,\nMore love, O Christ, to Thee,\nMore love to Thee;\nMore love to Thee.\n\nVerse 3\nThen shall my latest breath,\nWhisper Thy praise,\nThis be the parting cry\nMy heart shall raise;\nThis still its pray'r shall be,\nMore love, O Christ, to Thee,\nMore love to Thee;\nMore love to Thee.",
  "No, Not One": "Verse 2\nNo friend like Him is so high and holy,\nNo, not one!\nno, not one!\nAnd yet no friend is so meek and lowly,\nNo, not one!\nno, not one!\nJesus knows all about our struggles,\nHe will guide till the day is done;\nThere's not a friend like the lowly Jesus,\nNo, not one!\nno, not one!\n\nVerse 3\nThere's not an hour that He is not near us,\nNo, not one!\nno, not one!\nNo night so dark but His love can cheer us,\nNo, not one!\nno, not one!\nJesus knows all about our struggles,\nHe will guide till the day is done;\nThere's not a friend like the lowly Jesus,\nNo, not one!\nno, not one!\n\nVerse 4\nDid ever saint find this friend forsake him?\nNo, not one!\nno, not one!\nOr sinner find that He would not take him?\nNo, not one!\nno, not one!\nJesus knows all about our struggles,\nHe will guide till the day is done;\nThere's not a friend like the lowly Jesus,\nNo, not one!\nno, not one!\n\nVerse 5\nWas e'er a gift like the Savior given?\nNo, not one!\nno, not one!\nWill He refuse us a home in heaven?\nNo, not one!\nno, not one!\nJesus knows all about our struggles,\nHe will guide till the day is done;\nThere's not a friend like the lowly Jesus,\nNo, not one!\nno, not one!",
  "He Keeps Me Singing": "Verse 2\nAll my life was wrecked by sin and strife,\nDiscord filled my heart with pain,\nJesus swept across the broken strings,\nStirred the slumb'ring chords again.\nJesus, Jesus, Jesus,-\nSweetest name I know,\nFills my ev'ry longing,\nKeeps me singing as I go.\n\nVerse 3\nFeasting on the riches of His grace,\nResting 'neath His shelt'ring wing,\nAlways looking on His smiling face,\nThat is why I shout and sing.\nJesus, Jesus, Jesus,-\nSweetest name I know,\nFills my ev'ry longing,\nKeeps me singing as I go.\n\nVerse 4\nThough sometimes He leads through waters deep,\nTrials fall across the way,\nThough sometimes the path seems rough and steep,\nSee His footprints all the way.\nJesus, Jesus, Jesus,-\nSweetest name I know,\nFills my ev'ry longing,\nKeeps me singing as I go.\n\nVerse 5\nSoon He's coming back to welcome me,\nFar beyond the starry sky;\nI shall wing my flight to worlds unknown,\nI shall reign with Him on high.\nJesus, Jesus, Jesus,-\nSweetest name I know,\nFills my ev'ry longing,\nKeeps me singing as I go.",
  "Did You Think to Pray?": "Verse 2\ntalove Spirstay?\ndreapray.\n\nVerse 3\nangrace, noway?\ndreapray.\n\nVerse 4\non bowed\nborday? dreapray.",
  "Jesus Wants All Of His Children": "Verse 6\nto\n\nVerse 7\nAs\n\nVerse 8\nhelp\n\nVerse 9\nthus\n\nVerse 10\nwe"
};
